"""Semantic version ordering."""


def _pre_key(pre):
    # SemVer 2.0.0 §11: numeric identifiers compare numerically and sort
    # before alphanumeric ones; a shorter identifier list sorts first if
    # all preceding identifiers are equal (tuple comparison does that).
    parts = []
    for ident in pre.split("."):
        if ident.isdigit():
            parts.append((0, int(ident), ""))
        else:
            parts.append((1, 0, ident))
    return tuple(parts)


def key(version):
    """Sort key: a pre-release (1.0.0-alpha) sorts before its release (1.0.0)."""
    version = version.partition("+")[0]  # build metadata doesn't affect order
    core, _, pre = version.partition("-")
    nums = tuple(int(x) for x in core.split("."))
    if pre:
        return (nums, 0, _pre_key(pre))
    return (nums, 1, ())
