"""Caret ranges like ^1.2.3."""

from ver.order import key


def _upper(base):
    """Exclusive upper bound for ^base (npm/Cargo semantics)."""
    major, minor, patch = base
    if major > 0:
        return (major + 1, 0, 0)
    if minor > 0:
        return (0, minor + 1, 0)
    return (0, 0, patch + 1)


def satisfies(version, rng):
    """^X.Y.Z allows >= X.Y.Z and < (X+1).0.0 (for X > 0).

    For X == 0 the left-most non-zero component is fixed:
    ^0.Y.Z allows < 0.(Y+1).0 and ^0.0.Z allows < 0.0.(Z+1).
    """
    lower = rng.strip().lstrip("^")
    base = key(lower)[0]
    upper = _upper(base)
    k = key(version)
    return key(lower) <= k and k[0] < upper
